    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\r\n    def onesMinusZeros(self, grid: List[List[int]]) -> List[List[int]]:\r\n        Row, Col = len(grid), len(grid[0])\r\n        row = [0 for _ in range(Row)]\r\n        col = [0 for _ in range(Col)]\r\n        for r in range(Row):\r\n            cur = 0\r\n            for c in range(Col):\r\n                cur += grid[r][c]\r\n            row[r] = cur\r\n        for c in range(Col):\r\n            cur = 0\r\n            for r in range(Row):\r\n                cur += grid[r][c]\r\n            col[c] = cur\r\n        \r\n        res = [[0 for _ in range(Col)] for _ in range(Row)]\r\n        for r in range(Row):\r\n            for c in range(Col):\r\n                r1 = row[r]\r\n                c1 = col[c]\r\n                r0 = Row - r1\r\n                c0 = Col - c1\r\n                res[r][c] = r1 + c1 - r0 - c0\r\n        return res\r\n        \r\n        \r\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.onesMinusZeros(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
