    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def productExceptSelf(self, nums: List[int]) -> List[int]:\n        length = len(nums)\n        \n        # L \u548c R \u5206\u522b\u8868\u793a\u5de6\u53f3\u4e24\u4fa7\u7684\u4e58\u79ef\u5217\u8868\n        L, R, answer = [0]*length, [0]*length, [0]*length\n        \n        # L[i] \u4e3a\u7d22\u5f15 i \u5de6\u4fa7\u6240\u6709\u5143\u7d20\u7684\u4e58\u79ef\n        # \u5bf9\u4e8e\u7d22\u5f15\u4e3a '0' \u7684\u5143\u7d20\uff0c\u56e0\u4e3a\u5de6\u4fa7\u6ca1\u6709\u5143\u7d20\uff0c\u6240\u4ee5 L[0] = 1\n        L[0] = 1\n        for i in range(1, length):\n            L[i] = nums[i - 1] * L[i - 1]\n        \n        # R[i] \u4e3a\u7d22\u5f15 i \u53f3\u4fa7\u6240\u6709\u5143\u7d20\u7684\u4e58\u79ef\n        # \u5bf9\u4e8e\u7d22\u5f15\u4e3a 'length-1' \u7684\u5143\u7d20\uff0c\u56e0\u4e3a\u53f3\u4fa7\u6ca1\u6709\u5143\u7d20\uff0c\u6240\u4ee5 R[length-1] = 1\n        R[length - 1] = 1\n        for i in reversed(range(length - 1)):\n            R[i] = nums[i + 1] * R[i + 1]\n\n        # \u5bf9\u4e8e\u7d22\u5f15 i\uff0c\u9664 nums[i] \u4e4b\u5916\u5176\u4f59\u5404\u5143\u7d20\u7684\u4e58\u79ef\u5c31\u662f\u5de6\u4fa7\u6240\u6709\u5143\u7d20\u7684\u4e58\u79ef\u4e58\u4ee5\u53f3\u4fa7\u6240\u6709\u5143\u7d20\u7684\u4e58\u79ef\n        for i in range(length):\n            answer[i] = L[i] * R[i]\n        \n        return answer\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.productExceptSelf(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
